// Generated by crew — do not edit; it is rewritten every time the agent starts.
//
// This extension joins a pi session to the crew daemon:
// - the crew tools: crew's MCP server, registered with the session and
//   declared to the model like built-in tools (pi 1.0); on a pi without
//   MCP, each tool is registered as a pi tool that runs `crew ctl tool`;
// - the member's toolbox MCP servers, each reached through crew's proxy
//   (`crew toolbox mcp <name>`); the tools of all of them are in place, in
//   an order of crew's, before the first request (see `settle`);
// - team messages, pushed into the session over the daemon's Unix socket
//   (`crew bridge` holds it open and prints one JSON line per delivery);
// - the session's life, reported to the daemon (`crew hook …`): when it is
//   up, each turn, each tool call, the model and how full the context is;
// - compactions the daemon asks for, run between turns.
//
// Plain Node: no imports from pi itself, so it loads under any pi.
import { execFile, spawn } from "node:child_process"

const CREW_BIN: string = __CREW_BIN__
const IDENTITY: string = __IDENTITY__
// The member's toolbox MCP servers in name order: whether the member may
// not start without it, and the names of the tools its pinned snapshot
// serves.
const TOOLBOX_SERVERS: ToolboxServer[] = __TOOLBOX_SERVERS__

type Delivery = { ids: string[]; text: string }
type CompactOrder = { instructions?: string }
type ToolSpec = { name: string; description: string; inputSchema: unknown }
type Run = { code: number; stdout: string; stderr: string }
type ToolboxServer = { name: string; required: boolean; tools: string[] }
type ToolInfo = { name: string; exposure?: string; namespace?: { name?: string } }

const env = { ...process.env, CREW_IDENTITY: IDENTITY }

// A compaction the daemon asked for, waiting for the running turn to end.
let compactWhenIdle: CompactOrder | undefined
let compacting = false
let turnRunning = false
// What the session was last reported to run on.
let lastModel = ""
// crew starts every session with a prompt of its own (its task, a handoff,
// "you were restarted"), which pi takes once its MCP servers are up. Team
// messages that arrive before that turn starts wait for it: delivered
// first, they would run ahead of it — without the crew tools, and the
// prompt they overtook would be lost.
const FIRST_TURN_WAIT_MS = 30_000
let firstTurn = false
const held: string[] = []

function run(args: string[]): Promise<Run> {
  return new Promise(resolve => {
    execFile(CREW_BIN, args, { env, maxBuffer: 16 * 1024 * 1024 }, (error, stdout, stderr) => {
      const failed = error as (Error & { code?: unknown }) | null
      const code = failed === null ? 0 : typeof failed.code === "number" ? failed.code : 1
      resolve({ code, stdout: String(stdout ?? ""), stderr: String(stderr ?? "") })
    })
  })
}

function report(event: string, payload: object): void {
  void run(["hook", event, "--identity", IDENTITY, JSON.stringify(payload)])
}

function parse(line: string): Delivery | undefined {
  try {
    const value = JSON.parse(line)
    if (typeof value.text === "string" && Array.isArray(value.ids)) return value
  } catch {
    // not a delivery line
  }
  return undefined
}

function parseCompact(line: string): CompactOrder | undefined {
  try {
    const value = JSON.parse(line)
    if (value !== null && typeof value.compact === "object" && value.compact !== null) {
      const instructions = value.compact.instructions
      return typeof instructions === "string" && instructions !== "" ? { instructions } : {}
    }
  } catch {
    // not a compaction order
  }
  return undefined
}

function modelOf(ctx: any): { model?: string; effort?: string } {
  const model = ctx?.model
  const name = model === undefined ? undefined : model.provider ? `${model.provider}/${model.id}` : String(model.id)
  return { model: name, effort: undefined }
}

// What the session runs on, when it differs from the last report.
function reportModel(pi: any, ctx: any, event: string, extra: object = {}): void {
  const { model } = modelOf(ctx)
  let effort: string | undefined
  try {
    const level = pi.getThinkingLevel?.()
    if (typeof level === "string" && level !== "" && level !== "off") effort = level
  } catch {
    // no thinking level to speak of
  }
  const step = `${model ?? ""}\n${effort ?? ""}`
  if (step !== lastModel || event === "session-start") {
    lastModel = step
    report(event, { ...extra, model, effort })
  }
}

function reportUsage(ctx: any): void {
  try {
    const usage = ctx.getContextUsage?.()
    if (usage && typeof usage.tokens === "number" && typeof usage.contextWindow === "number") {
      report("usage", { context: { tokens: usage.tokens, window: usage.contextWindow } })
    }
  } catch {
    // nothing known yet
  }
}

// Compact the conversation between turns, as the daemon asked. One pi
// refuses (nothing to compact yet, the model unreachable) is reported, so
// the daemon stops asking; a failure to even ask is not, and it asks again.
function compact(ctx: any, order: CompactOrder): void {
  if (compacting) return
  compacting = true
  try {
    ctx.compact({
      ...(order.instructions === undefined ? {} : { customInstructions: order.instructions }),
      onComplete: () => {
        compacting = false
        report("compacted", {})
      },
      onError: (error: unknown) => {
        compacting = false
        report("compact-skipped", { reason: error instanceof Error ? error.message : String(error) })
      },
    })
  } catch {
    compacting = false
  }
}

async function deliver(pi: any, ctx: any, line: string): Promise<void> {
  const order = parseCompact(line)
  if (order !== undefined) {
    if (turnRunning) compactWhenIdle = order
    else compact(ctx, order)
    return
  }
  const delivery = parse(line)
  if (delivery === undefined) return
  // Idle: a turn of its own; mid-turn: queued until the turn ends.
  pi.sendUserMessage(delivery.text, { deliverAs: "followUp" })
  if (delivery.ids.length > 0) {
    await run(["delivered", "--identity", IDENTITY, ...delivery.ids])
  }
}

// Deliver what waited for the first turn (queued behind it, as follow-ups).
function release(pi: any, ctx: any): void {
  if (firstTurn) return
  firstTurn = true
  for (const line of held.splice(0)) void deliver(pi, ctx, line)
}

function pump(pi: any, ctx: any): void {
  // Should pi never start the first turn once its tools are in place,
  // messages are not held forever.
  void settled(pi, ctx).then(() => setTimeout(() => release(pi, ctx), FIRST_TURN_WAIT_MS).unref?.())
  const bridge = spawn(CREW_BIN, ["bridge", "--identity", IDENTITY], { env, stdio: ["ignore", "pipe", "ignore"] })
  let buffer = ""
  bridge.stdout.setEncoding("utf8")
  bridge.stdout.on("data", (chunk: string) => {
    buffer += chunk
    let newline = buffer.indexOf("\n")
    while (newline >= 0) {
      const line = buffer.slice(0, newline)
      buffer = buffer.slice(newline + 1)
      newline = buffer.indexOf("\n")
      if (line.trim() === "") continue
      if (firstTurn) void deliver(pi, ctx, line)
      else held.push(line)
    }
  })
  bridge.on("error", () => {
    // Without the bridge the daemon falls back to the terminal.
  })
  process.on("exit", () => {
    try {
      bridge.kill()
    } catch {
      // already gone
    }
  })
}

// The MCP servers crew registers: its own, then the toolbox's in name order.
// A toolbox server says which tools to wait for; crew's own lists them all
// at once (pi registers each listing in one go), so any of them will do.
type Server = { name: string; required: boolean; config: object; tools?: string[] }
const SERVERS: Server[] = [
  {
    name: "crew",
    required: true,
    config: {
      command: CREW_BIN,
      args: ["mcp", "--identity", IDENTITY],
      description: "Your crew team: messages, tasks, reviews and git, as the briefing describes",
    },
  },
  ...TOOLBOX_SERVERS.map(server => ({
    name: server.name,
    required: server.required,
    config: { command: CREW_BIN, args: ["toolbox", "mcp", server.name, "--identity", IDENTITY] },
    tools: server.tools,
  })),
]
// How long the first request waits for each server to list its tools.
// crew's proxy answers from the pinned snapshot, so only a server that
// cannot start at all takes this long.
const SERVER_WAIT_MS = 10_000
// Started once per process; the first request, and every one after it,
// waits for it.
let settling: Promise<void> | undefined

// Whether this pi lets crew put the tools in place before the first request.
function orders(pi: any): boolean {
  return typeof pi.getAllTools === "function" && typeof pi.setActiveTools === "function"
}

function register(pi: any, server: Server): boolean {
  try {
    pi.registerMcpServer(server.name, { ...server.config, exposure: "direct" })
    return true
  } catch {
    // An invalid name, or one another server already has: pi says so.
    return false
  }
}

async function registerTools(pi: any): Promise<void> {
  if (typeof pi.registerMcpServer === "function") {
    // The toolbox's servers follow crew's one at a time (`settle`), unless
    // this pi cannot be waited on.
    for (const server of orders(pi) ? SERVERS.slice(0, 1) : SERVERS) register(pi, server)
    return
  }
  const listed = await run(["ctl", "tools"])
  if (listed.code !== 0) return
  let specs: ToolSpec[]
  try {
    specs = JSON.parse(listed.stdout)
  } catch {
    return
  }
  for (const spec of specs) {
    if (typeof spec.name !== "string") continue
    pi.registerTool({
      name: spec.name,
      label: spec.name,
      description: spec.description,
      parameters: spec.inputSchema,
      async execute(_toolCallId: string, params: unknown) {
        const result = await run(["ctl", "tool", spec.name, JSON.stringify(params ?? {})])
        const text = result.code === 0 ? result.stdout.trimEnd() : `Error: ${(result.stderr || result.stdout).trim()}`
        return { content: [{ type: "text", text: text === "" ? "ok" : text }], details: {} }
      },
    })
  }
}

// pi's group of a server's tools, and the name it gives a tool: both as its
// MCP documentation says.
function namespaceOf(server: string): string {
  return `mcp__${server.replace(/-/g, "_")}`
}

function toolName(server: string, tool: string): string {
  return `mcp__${server}__${tool}`.replace(/[^A-Za-z0-9_]/g, "_")
}

// The tools pi has registered for the server, not withdrawn.
function toolsOf(pi: any, server: Server): string[] {
  const namespace = namespaceOf(server.name)
  return (pi.getAllTools() as ToolInfo[])
    .filter(tool => tool.namespace?.name === namespace && tool.exposure !== "hidden")
    .map(tool => tool.name)
}

// Whether every tool the server is expected to list is registered. A name
// pi has to change (too long, or the same as another tool's) is counted
// rather than looked for: pi gives it a suffix of its own.
function listed(pi: any, server: Server, taken: Set<string>): boolean {
  const present = toolsOf(pi, server)
  if (server.tools === undefined) return present.length > 0
  if (present.length < server.tools.length) return false
  const names = server.tools.map(tool => toolName(server.name, tool))
  return names.every(
    name => name.length > 64 || taken.has(name) || names.indexOf(name) !== names.lastIndexOf(name) || present.includes(name),
  )
}

async function arrived(pi: any, server: Server, taken: Set<string>): Promise<boolean> {
  const deadline = Date.now() + SERVER_WAIT_MS
  while (!listed(pi, server, taken)) {
    if (Date.now() >= deadline) return false
    await new Promise(resolve => setTimeout(resolve, 20))
  }
  return true
}

// pi connects MCP servers in the background and declares each one's tools
// to the model as it connects: left alone, the tools follow the order in
// which the servers happened to answer, a name two servers' tools share
// goes to whichever answered first, and a server that answers late joins
// after the first request. So crew registers its servers one at a time,
// each once the one before has listed its tools, waits for all of them,
// then declares the tools in its own order: pi's own and other extensions'
// as they are, then crew's, then each toolbox server's in name order, then
// any other server's, each server's tools by name. The same toolbox gives
// the same tool list, byte for byte, on every start and restart.
//
// A required server (crew's own, or one the toolbox requires) that does not
// list its tools in time ends the session before its first request; another
// is left out of the session, and the daemon told.
async function settle(pi: any, ctx: any): Promise<void> {
  const ready: Server[] = []
  const taken = new Set<string>()
  for (const [index, server] of SERVERS.entries()) {
    if (index > 0 && server.tools?.length === 0) {
      // Nothing to declare and nothing to wait for.
      register(pi, server)
      continue
    }
    const registered = index === 0 || register(pi, server)
    if (registered && (await arrived(pi, server, taken))) {
      ready.push(server)
      for (const name of toolsOf(pi, server)) taken.add(name)
      continue
    }
    const why = registered
      ? `${server.name} did not list its tools within ${SERVER_WAIT_MS / 1000} s`
      : `pi did not take ${server.name} as an MCP server`
    if (index > 0) {
      report("toolbox-failed", {
        server: server.name,
        detail: server.required ? `${why}; it is required, so the session ended before its first request` : `${why}; the session runs without it`,
      })
    }
    if (server.required) return stop(ctx, `${why}, and the session cannot run without it`)
    // Its tools must not join the session later.
    try {
      pi.unregisterMcpServer?.(server.name)
    } catch {
      // never registered
    }
    notify(ctx, `${why}: the session runs without it.`, "warning")
  }
  const rank = new Map(ready.map((server, index) => [namespaceOf(server.name), index]))
  const groups = new Map<string, string>()
  for (const tool of pi.getAllTools() as ToolInfo[]) {
    if (tool.namespace?.name !== undefined) groups.set(tool.name, tool.namespace.name)
  }
  const key = (name: string): [number, string, string] => {
    const group = groups.get(name) ?? ""
    return [rank.get(group) ?? ready.length, group, name]
  }
  const active: string[] = pi.getActiveTools()
  const servers = active.filter(name => name.startsWith("mcp__"))
  servers.sort((a, b) => {
    const [x, y] = [key(a), key(b)]
    return x[0] - y[0] || compare(x[1], y[1]) || compare(x[2], y[2])
  })
  const order = [...active.filter(name => !name.startsWith("mcp__")), ...servers]
  if (order.some((name, index) => name !== active[index])) pi.setActiveTools(order)
}

// By code unit, the same in every locale.
function compare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0
}

function notify(ctx: any, text: string, kind: string): void {
  try {
    ctx.ui?.notify?.(`crew: ${text}`, kind)
  } catch {
    // no screen to say it on
  }
}

// End the session without a request: nothing that waits for the tools is
// let through, and pi exits (the daemon sees the member stop).
function stop(ctx: any, why: string): Promise<void> {
  notify(ctx, `${why}; ending the session before its first request.`, "error")
  try {
    ctx.shutdown()
  } catch {
    // the session is already going
  }
  return new Promise(() => {})
}

// The tools are in place (immediately on a pi that cannot be waited on).
function settled(pi: any, ctx: any): Promise<void> {
  settling ??= orders(pi) ? settle(pi, ctx) : Promise.resolve()
  return settling
}

export default async function (pi: any): Promise<void> {
  await registerTools(pi)
  let pumping = false

  // Every request waits until the tools are in place.
  pi.on("before_agent_start", (_event: unknown, ctx: any) => settled(pi, ctx))

  pi.on("session_start", (_event: unknown, ctx: any) => {
    const manager = ctx.sessionManager
    report("session-start", {
      session_id: manager?.getSessionId?.(),
      transcript_path: manager?.getSessionFile?.(),
      ...modelOf(ctx),
    })
    lastModel = ""
    void settled(pi, ctx)
    if (!pumping) {
      pumping = true
      pump(pi, ctx)
    }
  })

  pi.on("agent_start", (_event: unknown, ctx: any) => {
    turnRunning = true
    reportModel(pi, ctx, "model")
    report("turn-start", {})
    release(pi, ctx)
  })

  pi.on("model_select", (_event: unknown, ctx: any) => {
    reportModel(pi, ctx, "model")
  })

  pi.on("tool_execution_start", (event: any) => {
    report("tool-start", { tool_name: event.toolName, tool_input: event.args })
  })

  pi.on("agent_end", (event: any, ctx: any) => {
    turnRunning = false
    const messages: any[] = Array.isArray(event?.messages) ? event.messages : []
    const last = [...messages].reverse().find(m => m?.role === "assistant")
    const payload: Record<string, unknown> = {}
    if (last?.stopReason === "error") {
      payload.error = "error"
      payload.error_details = String(last.errorMessage ?? "")
    }
    report("turn-end", payload)
    reportUsage(ctx)
    if (compactWhenIdle !== undefined) {
      const order = compactWhenIdle
      compactWhenIdle = undefined
      compact(ctx, order)
    }
  })

  pi.on("session_compact", () => {
    report("compacted", {})
  })

  pi.on("session_shutdown", () => {
    report("exiting", {})
  })
}
